const PATCH_MARKER = 'dsh-theme-liquid-glass: the recipe';
const SCAN_CHUNK = 4 * 1024 * 1024;

/** Where tools/asarpatch.py records the archive it patched. */
const POINTER_FILE = path.join(STORE_DIR, 'asar-pointer.json');

/**
